#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_CONNECTIONS 64
#define BUFFER_SIZE 4096
#define SECRET_KEY_LEN 32
#define TELEMETRY_PORT 8443

typedef struct {
    char device_id[64];
    char api_secret[SECRET_KEY_LEN + 1];
    unsigned long uptime_seconds;
    int firmware_version;
} device_context_t;

typedef struct {
    char *payload;
    size_t payload_len;
    size_t capacity;
    int status_code;
} response_buffer_t;

static device_context_t g_device_ctx;
static pthread_mutex_t ctx_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_device_context(void) {
    pthread_mutex_lock(&ctx_mutex);
    strncpy(g_device_ctx.device_id, "iot-sensor-node-7f3a", sizeof(g_device_ctx.device_id) - 1);
    g_device_ctx.device_id[sizeof(g_device_ctx.device_id) - 1] = '\0';
    const char *k8s_secret = getenv("K8S_DEVICE_API_SECRET");
    if (k8s_secret) {
        strncpy(g_device_ctx.api_secret, k8s_secret, SECRET_KEY_LEN);
        g_device_ctx.api_secret[SECRET_KEY_LEN] = '\0';
    }
    g_device_ctx.uptime_seconds = 0;
    g_device_ctx.firmware_version = 0x0204;
    pthread_mutex_unlock(&ctx_mutex);
}

response_buffer_t *create_response(size_t initial_capacity) {
    response_buffer_t *resp = (response_buffer_t *)malloc(sizeof(response_buffer_t));
    if (!resp) return NULL;
    resp->payload = (char *)malloc(initial_capacity);
    if (!resp->payload) {
        free(resp);
        return NULL;
    }
    resp->capacity = initial_capacity;
    resp->payload_len = 0;
    resp->status_code = 200;
    return resp;
}

int append_response(response_buffer_t *resp, const char *data, size_t len) {
    if (resp->payload_len + len > resp->capacity) {
        size_t new_cap = resp->capacity * 2;
        while (new_cap < resp->payload_len + len) new_cap *= 2;
        char *new_buf = (char *)realloc(resp->payload, new_cap);
        if (!new_buf) return -1;
        resp->payload = new_buf;
        resp->capacity = new_cap;
    }
    memcpy(resp->payload + resp->payload_len, data, len);
    resp->payload_len += len;
    return 0;
}

void free_response(response_buffer_t *resp) {
    if (resp) {
        free(resp->payload);
        free(resp);
    }
}

int build_health_response(response_buffer_t *resp) {
    char temp[512];
    pthread_mutex_lock(&ctx_mutex);
    int n = snprintf(temp, sizeof(temp),
        "{\"device_id\":\"%s\",\"uptime\":%lu,\"fw_version\":\"0x%04x\",\"status\":\"healthy\"}",
        g_device_ctx.device_id, g_device_ctx.uptime_seconds, g_device_ctx.firmware_version);
    pthread_mutex_unlock(&ctx_mutex);
    if (n < 0) return -1;
    /* Clamp to actual buffer size to avoid OOB read on snprintf truncation */
    if ((size_t)n >= sizeof(temp)) n = (int)sizeof(temp) - 1;
    return append_response(resp, temp, (size_t)n);
}

int build_telemetry_response(response_buffer_t *resp, const char *request_body, size_t body_len) {
    char staging[BUFFER_SIZE];
    memset(staging, 0, sizeof(staging));

    pthread_mutex_lock(&ctx_mutex);
    /* Copy only non-sensitive fields into staging area for telemetry assembly */
    strncpy(staging, g_device_ctx.device_id, sizeof(g_device_ctx.device_id));
    unsigned long uptime_copy = g_device_ctx.uptime_seconds;
    int fw_copy = g_device_ctx.firmware_version;
    pthread_mutex_unlock(&ctx_mutex);

    /* Build the telemetry JSON using only safe fields from staging */
    char output[1024];
    int n = snprintf(output, sizeof(output),
        "{\"device_id\":\"%s\",\"telemetry_ack\":true,\"payload_received\":%zu}",
        staging, body_len);
    if (n < 0) return -1;
    /* Clamp to actual buffer size to avoid OOB read on snprintf truncation */
    if ((size_t)n >= sizeof(output)) n = (int)sizeof(output) - 1;

    if (append_response(resp, output, (size_t)n) != 0) return -1;

    /* Diagnostic trailer: include only non-sensitive metadata for k8s sidecar
       attestation verification - uptime and firmware version only */
    char hex_trailer[512];
    int hex_pos = 0;
    int r = snprintf(hex_trailer + hex_pos, sizeof(hex_trailer) - hex_pos, ",\"diag\":\"");
    if (r > 0 && r < (int)sizeof(hex_trailer) - hex_pos) hex_pos += r;
    unsigned char *uptime_bytes = (unsigned char *)&uptime_copy;
    for (size_t i = 0; i < sizeof(unsigned long) && hex_pos < (int)sizeof(hex_trailer) - 4; i++) {
        r = snprintf(hex_trailer + hex_pos, sizeof(hex_trailer) - hex_pos, "%02x", uptime_bytes[i]);
        if (r > 0 && r < (int)sizeof(hex_trailer) - hex_pos) hex_pos += r;
    }
    unsigned char *fw_bytes = (unsigned char *)&fw_copy;
    for (size_t i = 0; i < sizeof(int) && hex_pos < (int)sizeof(hex_trailer) - 4; i++) {
        r = snprintf(hex_trailer + hex_pos, sizeof(hex_trailer) - hex_pos, "%02x", fw_bytes[i]);
        if (r > 0 && r < (int)sizeof(hex_trailer) - hex_pos) hex_pos += r;
    }
    r = snprintf(hex_trailer + hex_pos, sizeof(hex_trailer) - hex_pos, "\"}");
    if (r > 0 && r < (int)sizeof(hex_trailer) - hex_pos) hex_pos += r;

    return append_response(resp, hex_trailer, (size_t)hex_pos);
}

void *handle_connection(void *arg) {
    int client_fd = *(int *)arg;
    free(arg);

    char request[BUFFER_SIZE];
    ssize_t bytes_read = read(client_fd, request, sizeof(request) - 1);
    if (bytes_read <= 0) {
        close(client_fd);
        return NULL;
    }
    request[bytes_read] = '\0';

    response_buffer_t *resp = create_response(1024);
    if (!resp) {
        close(client_fd);
        return NULL;
    }

    if (strstr(request, "GET /health")) {
        build_health_response(resp);
    } else if (strstr(request, "POST /telemetry")) {
        char *body = strstr(request, "\r\n\r\n");
        size_t body_len = 0;
        if (body) {
            body += 4;
            body_len = bytes_read - (body - request);
        }
        build_telemetry_response(resp, body, body_len);
    } else {
        const char *not_found = "{\"error\":\"not found\"}";
        append_response(resp, not_found, strlen(not_found));
        resp->status_code = 404;
    }

    char header[256];
    int hlen = snprintf(header, sizeof(header),
        "HTTP/1.1 %d OK\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n",
        resp->status_code, resp->payload_len);
    if (hlen > 0) {
        if (hlen >= (int)sizeof(header)) hlen = (int)sizeof(header) - 1;
        write(client_fd, header, hlen);
    }
    write(client_fd, resp->payload, resp->payload_len);

    free_response(resp);
    close(client_fd);
    return NULL;
}

int main(void) {
    init_device_context();

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(TELEMETRY_PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) return 1;
    if (listen(server_fd, MAX_CONNECTIONS) < 0) return 1;

    while (1) {
        int *client_fd = malloc(sizeof(int));
        if (!client_fd) continue;
        *client_fd = accept(server_fd, NULL, NULL);
        if (*client_fd < 0) { free(client_fd); continue; }

        pthread_t tid;
        pthread_create(&tid, NULL, handle_connection, client_fd);
        pthread_detach(tid);

        pthread_mutex_lock(&ctx_mutex);
        g_device_ctx.uptime_seconds += 1;
        pthread_mutex_unlock(&ctx_mutex);
    }

    close(server_fd);
    return 0;
}
